package designconvert

import (
	"bytes"
	"fmt"
	"go/ast"
	goparser "go/parser"
	"go/token"
	"io"
	"net/url"
	"strconv"
	"strings"
	"unicode/utf8"

	"github.com/a-h/templ"
	templparser "github.com/a-h/templ/parser/v2"
	"golang.org/x/net/html"
	"golang.org/x/net/html/atom"
)

const (
	MaxSourceBytes = 256 << 10
	MaxDiagnostics = 64
	maxTokens      = 20000
	maxDepth       = 128
	maxAttributes  = 128
	maxOutputBytes = 4 << 20
)

// HTMLResult is syntax translation only. No source is emitted when any input is
// unsupported. Mappings address original and generated bytes, not rendered DOM.
type HTMLResult struct {
	Templ              string       `json:"templ"`
	Diagnostics        []Diagnostic `json:"diagnostics"`
	Mappings           []Mapping    `json:"mappings"`
	OmittedDiagnostics int          `json:"omitted_diagnostics"`
}

type Diagnostic struct {
	Code    string `json:"code"`
	Message string `json:"message"`
	Offset  int    `json:"offset"`
}

type Mapping struct {
	SourceStart int `json:"source_start"`
	SourceEnd   int `json:"source_end"`
	OutputStart int `json:"output_start"`
	OutputEnd   int `json:"output_end"`
}

type htmlPart struct {
	token             html.Token
	start, end, depth int
}

type htmlFrame struct {
	name string
	svg  bool
}

// HTMLToTempl accepts a deliberately bounded HTML fragment grammar, not JSX,
// arbitrary documents, scripts, CSS, custom elements, or behavior directives.
// Native HTML semantics and literal classes/attributes/text are retained; runtime,
// asset, accessibility and visual suitability require separate evidence. It never
// executes source, uses templ.Raw, installs dependencies, or emits configurable Go.
func HTMLToTempl(source []byte) (HTMLResult, error) {
	r := HTMLResult{Diagnostics: []Diagnostic{}, Mappings: []Mapping{}}
	add := func(code, message string, offset int) {
		if len(r.Diagnostics) == MaxDiagnostics {
			r.OmittedDiagnostics++
			return
		}
		r.Diagnostics = append(r.Diagnostics, Diagnostic{Code: code, Message: message, Offset: offset})
	}
	if len(source) > MaxSourceBytes {
		add("source-limit", "HTML source exceeds the 256 KiB translation limit.", 0)
		return r, nil
	}
	if !utf8.Valid(source) || bytes.IndexByte(source, 0) >= 0 {
		add("source-encoding", "HTML source must be UTF-8 text without NUL bytes.", 0)
		return r, nil
	}
	if invalidControl(string(source), true) {
		add("source-control", "HTML source contains unsupported control characters.", 0)
		return r, nil
	}
	z := html.NewTokenizer(bytes.NewReader(source))
	z.SetMaxBuf(MaxSourceBytes)
	parts := make([]htmlPart, 0)
	stack := make([]htmlFrame, 0)
	offset, elements := 0, 0
	for {
		tt := z.Next()
		// Token() may decode entities in the tokenizer's backing buffer.
		// Keep original spelling for lexical checks and byte offsets.
		raw := bytes.Clone(z.Raw())
		start := offset
		offset += len(raw)
		if tt == html.ErrorToken {
			if z.Err() != io.EOF || len(raw) != 0 {
				add("html-syntax", "HTML tokenization failed or ended inside a token.", start)
			}
			break
		}
		if len(parts) == maxTokens {
			add("token-limit", "HTML fragment exceeds the token limit.", start)
			break
		}
		t := z.Token()
		depth := len(stack)
		svg := len(stack) > 0 && stack[len(stack)-1].svg
		switch tt {
		case html.StartTagToken, html.SelfClosingTagToken:
			elements++
			if !validTagSyntax(raw, false) {
				add("html-syntax", "Tags require explicit well-formed syntax and quoted attribute values.", start)
			}
			if t.Data == "svg" {
				svg = true
			}
			if !allowedTag(t.Data, svg) {
				add("unsupported-element", "Element is outside the HTML/basic-SVG grammar; scripts, styles and custom runtimes require a reviewed adapter.", start)
			}
			if len(t.Attr) > maxAttributes {
				add("attribute-limit", "Element exceeds the attribute limit.", start)
			}
			seen := make(map[string]bool, len(t.Attr))
			for _, attr := range t.Attr {
				if seen[attr.Key] {
					add("duplicate-attribute", "Duplicate HTML attribute names are unsupported.", start)
				}
				seen[attr.Key] = true
				if !allowedAttribute(attr.Key, svg) {
					add("unsupported-attribute", "Attribute is outside the literal grammar; inline styles, events and behavior directives require a reviewed adapter.", start)
				}
				if invalidControl(attr.Val, false) {
					add("attribute-control", "Decoded attribute contains unsupported control characters or a carriage-return entity.", start)
				}
				if !safeAttributeValue(t.Data, attr.Key, attr.Val, svg) {
					add("unsafe-resource", "Attribute uses an unsupported URL, resource reference or CSS expression.", start)
				}
			}
			if tt == html.SelfClosingTagToken && !svg && !voidTags[t.Data] {
				add("html-self-closing", "Non-void HTML elements need explicit closing tags; slash syntax does not close them in HTML.", start)
			}
			if !svg && invalidParent(stack, t.Data) {
				add("html-nesting", "Element nesting requires browser repair and is outside the explicit fragment grammar.", start)
			}
			if tt != html.SelfClosingTagToken && !(voidTags[t.Data] && !svg) {
				if len(stack) == maxDepth {
					add("depth-limit", "HTML fragment exceeds the nesting limit.", start)
					return r, nil
				}
				stack = append(stack, htmlFrame{t.Data, svg})
			}
		case html.EndTagToken:
			if !validTagSyntax(raw, true) {
				add("html-syntax", "Closing tags may not carry attributes or slash modifiers.", start)
			}
			if len(stack) == 0 || stack[len(stack)-1].name != t.Data {
				add("html-nesting", "Closing tags must exactly match explicitly opened elements.", start)
			} else {
				stack = stack[:len(stack)-1]
				depth = len(stack)
			}
		case html.TextToken:
			if invalidControl(t.Data, false) {
				add("text-control", "Decoded text contains unsupported control characters or a carriage-return entity.", start)
			}
		case html.CommentToken:
			if !bytes.HasPrefix(raw, []byte("<!--")) || !bytes.HasSuffix(raw, []byte("-->")) ||
				strings.Contains(t.Data, "--") || strings.HasSuffix(t.Data, "-") || strings.HasPrefix(t.Data, ">") ||
				strings.HasPrefix(t.Data, "[if") || invalidControl(t.Data, false) {
				add("unsupported-comment", "Only ordinary, well-formed HTML comments are supported; declarations, CDATA and conditional comments require review.", start)
			}
		default:
			add("unsupported-document", "Only HTML fragments are supported; document declarations require a separate adapter.", start)
		}
		parts = append(parts, htmlPart{token: t, start: start, end: offset, depth: depth})
	}
	if len(stack) != 0 {
		add("html-nesting", "HTML fragment ends with unclosed elements.", len(source))
	}
	if elements == 0 {
		add("html-fragment", "Translation requires an HTML element, not an empty input or another source language.", 0)
	}
	if len(r.Diagnostics) != 0 {
		return r, nil
	}
	if !sameExplicitTree(source, parts) {
		add("html-tree-repair", "The HTML parser changes the explicit fragment tree; implicit insertion, closure or reparenting needs a reviewed adapter.", 0)
		return r, nil
	}

	var out strings.Builder
	out.WriteString("package converted\n\ntempl Specimen() {\n")
	for _, p := range parts {
		begin := out.Len()
		indent := strings.Repeat("\t", p.depth+1)
		// A Go-comment node is a non-rendering barrier in pinned templ. Without
		// these, formatting inserts spaces between adjacent inline/text nodes.
		if p.token.Type != html.EndTagToken {
			fmt.Fprintf(&out, "%s// source bytes %d..%d\n", indent, p.start, p.end)
		}
		out.WriteString(indent)
		switch p.token.Type {
		case html.StartTagToken, html.SelfClosingTagToken:
			out.WriteByte('<')
			out.WriteString(p.token.Data)
			for _, a := range p.token.Attr {
				// Constant class attributes are normalized by templ's generator.
				// Literal string expressions retain class spacing and duplication.
				fmt.Fprintf(&out, " %s={ %s }", a.Key, strconv.Quote(a.Val))
			}
			if p.token.Type == html.SelfClosingTagToken || voidTags[p.token.Data] {
				out.WriteString("/>")
			} else {
				out.WriteByte('>')
			}
		case html.EndTagToken:
			fmt.Fprintf(&out, "</%s>", p.token.Data)
		case html.TextToken:
			fmt.Fprintf(&out, "{ %s }", strconv.Quote(p.token.Data))
		case html.CommentToken:
			fmt.Fprintf(&out, "<!--%s-->", p.token.Data)
		}
		out.WriteByte('\n')
		r.Mappings = append(r.Mappings, Mapping{p.start, p.end, begin, out.Len()})
		if out.Len() > maxOutputBytes {
			add("output-limit", "Translated source exceeds the output limit.", p.start)
			r.Mappings = []Mapping{}
			return r, nil
		}
	}
	out.WriteString("}\n")
	if err := validateTempl(out.String()); err != nil {
		return HTMLResult{}, err
	}
	r.Templ = out.String()
	return r, nil
}

func words(s string) map[string]bool {
	m := make(map[string]bool)
	for _, s := range strings.Fields(s) {
		m[s] = true
	}
	return m
}

var htmlTags = words(`a abbr address article aside b bdi bdo blockquote br button caption cite code col colgroup data datalist dd del details dfn dialog div dl dt em fieldset figcaption figure footer form h1 h2 h3 h4 h5 h6 header hgroup hr i img input ins kbd label legend li main map mark menu meter nav ol optgroup option output p picture pre progress q rp rt ruby s samp search section select slot small source span strong sub summary sup table tbody td textarea tfoot th thead time tr u ul var wbr`)
var svgTags = words(`svg g path rect circle ellipse line polyline polygon text tspan title desc defs symbol use clippath mask pattern marker lineargradient radialgradient stop`)
var voidTags = words(`br col hr img input source wbr`)
var htmlAttributes = words(`id class title role tabindex hidden inert lang dir translate accesskey draggable contenteditable spellcheck slot href target rel download hreflang type referrerpolicy ping name value disabled checked selected required readonly multiple placeholder autocomplete autofocus min max step minlength maxlength pattern size rows cols wrap accept capture alt src width height loading decoding fetchpriority sizes media for form action method enctype novalidate formnovalidate formaction formenctype formmethod formtarget list label open popover popovertarget popovertargetaction command commandfor scope headers colspan rowspan abbr span start reversed high low optimum datetime cite controls loop muted poster preload playsinline usemap ismap shape coords kind srclang default`)
var svgAttributes = words(`id class role tabindex aria-hidden focusable xmlns xmlns:xlink viewbox preserveaspectratio width height x y x1 y1 x2 y2 cx cy r rx ry d points pathlength transform opacity fill fill-rule fill-opacity stroke stroke-width stroke-linecap stroke-linejoin stroke-miterlimit stroke-dasharray stroke-dashoffset stroke-opacity clip-rule clip-path mask filter marker-start marker-mid marker-end vector-effect color href xlink:href offset stop-color stop-opacity gradientunits gradienttransform spreadmethod fx fy fr patternunits patterncontentunits patterntransform markerwidth markerheight markerunits orient refx refy text-anchor dominant-baseline font-size font-family font-weight textlength lengthadjust dx dy rotate`)

func allowedTag(name string, svg bool) bool {
	if svg {
		return svgTags[name]
	}
	return htmlTags[name]
}

func allowedAttribute(name string, svg bool) bool {
	if !attributeName(name) || name == "style" || strings.HasPrefix(name, "on") {
		return false
	}
	// Generic data attributes remain literal metadata. Known expression-bearing
	// namespaces are refused, including modifiers such as data-on:click.
	for _, p := range []string{"x-", "v-", "data-on", "data-bind", "data-signals", "data-computed", "data-effect", "data-init", "data-text", "data-show", "data-class", "data-attr", "data-style", "data-ref", "data-indicator", "data-preserve", "data-ignore", "data-json-signals"} {
		if strings.HasPrefix(name, p) {
			return false
		}
	}
	if strings.HasPrefix(name, "aria-") || strings.HasPrefix(name, "data-") {
		return len(name) > 5 && !strings.ContainsRune(name, ':')
	}
	if svg {
		return svgAttributes[name]
	}
	return htmlAttributes[name]
}

func attributeName(s string) bool {
	if len(s) == 0 || len(s) > 128 {
		return false
	}
	for _, c := range s {
		if c < 'a' || c > 'z' {
			if c != '-' && c != ':' && (c < '0' || c > '9') {
				return false
			}
		}
	}
	return s[0] >= 'a' && s[0] <= 'z'
}

func invalidControl(s string, raw bool) bool {
	for _, c := range s {
		if c == '\r' && raw {
			continue
		}
		if c < 32 && c != '\n' && c != '\t' || c >= 0x7f && c <= 0x9f {
			return true
		}
	}
	return false
}

// The HTML tokenizer deliberately accepts browser error recovery. This small
// lexical gate excludes malformed tags without attempting to repair them. Bare
// presence attributes are supported; assigned values must be quoted in v1.
func validTagSyntax(raw []byte, closing bool) bool {
	i := 1
	if closing {
		i++
	}
	name := func(c byte) bool {
		return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '-' || c == ':' || c == '_'
	}
	space := func(c byte) bool { return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' }
	start := i
	for i < len(raw) && name(raw[i]) {
		i++
	}
	if i == start {
		return false
	}
	for i < len(raw) {
		before := i
		for i < len(raw) && space(raw[i]) {
			i++
		}
		if i == len(raw) {
			return false
		}
		if raw[i] == '>' {
			return i == len(raw)-1
		}
		if closing {
			return false
		}
		if raw[i] == '/' {
			return i == len(raw)-2 && raw[i+1] == '>'
		}
		if i == before {
			return false
		}
		start = i
		for i < len(raw) && name(raw[i]) {
			i++
		}
		if start == i {
			return false
		}
		end := i
		for i < len(raw) && space(raw[i]) {
			i++
		}
		if i == len(raw) {
			return false
		}
		if raw[i] != '=' {
			i = end
			continue
		}
		i++
		for i < len(raw) && space(raw[i]) {
			i++
		}
		if i == len(raw) || raw[i] != '\'' && raw[i] != '"' {
			return false
		}
		quote := raw[i]
		i++
		for i < len(raw) && raw[i] != quote {
			i++
		}
		if i == len(raw) {
			return false
		}
		i++
	}
	return false
}

type treeEvent struct {
	kind html.TokenType
	data string
}

// Compare the explicit source-token tree with the browser parser's fragment
// tree. This detects permissive parser repairs, not HTML conformance, labels,
// accessibility, asset availability, runtime behavior or visual equivalence.
func sameExplicitTree(source []byte, parts []htmlPart) bool {
	want := make([]treeEvent, 0, len(parts))
	for i, p := range parts {
		t := p.token
		switch t.Type {
		case html.StartTagToken, html.SelfClosingTagToken:
			want = append(want, treeEvent{html.StartTagToken, t.Data})
			if t.Type == html.SelfClosingTagToken || voidTags[t.Data] {
				want = append(want, treeEvent{html.EndTagToken, t.Data})
			}
		case html.TextToken:
			// The HTML parser consumes one initial LF in pre/textarea. Retain
			// that original LF in emitted source so the rendered parser does so
			// exactly once; do not emit already-normalized DOM text instead.
			data := t.Data
			if i > 0 && parts[i-1].token.Type == html.StartTagToken && (parts[i-1].token.Data == "pre" || parts[i-1].token.Data == "textarea") {
				data = strings.TrimPrefix(data, "\n")
			}
			if data != "" {
				want = append(want, treeEvent{html.TextToken, data})
			}
		default:
			want = append(want, treeEvent{t.Type, t.Data})
		}
	}
	nodes, err := html.ParseFragment(bytes.NewReader(source), &html.Node{Type: html.ElementNode, Data: "div", DataAtom: atom.Div})
	if err != nil {
		return false
	}
	got := make([]treeEvent, 0, len(want))
	var visit func(*html.Node)
	visit = func(n *html.Node) {
		switch n.Type {
		case html.ElementNode:
			// HTML parsing restores SVG's standard mixed-case spellings. Both
			// source and emitted HTML are compared namespace-aware in compiler
			// regressions; this structural gate ignores spelling normalization.
			got = append(got, treeEvent{html.StartTagToken, strings.ToLower(n.Data)})
			for c := n.FirstChild; c != nil; c = c.NextSibling {
				visit(c)
			}
			got = append(got, treeEvent{html.EndTagToken, strings.ToLower(n.Data)})
		case html.TextNode:
			got = append(got, treeEvent{html.TextToken, n.Data})
		case html.CommentNode:
			got = append(got, treeEvent{html.CommentToken, n.Data})
		default:
			got = append(got, treeEvent{html.ErrorToken, ""})
		}
	}
	for _, n := range nodes {
		visit(n)
	}
	if len(got) != len(want) {
		return false
	}
	for i := range want {
		if got[i] != want[i] {
			return false
		}
	}
	return true
}

func safeAttributeValue(tag, key, value string, svg bool) bool {
	if key == "xmlns" {
		return svg && value == "http://www.w3.org/2000/svg"
	}
	if key == "xmlns:xlink" {
		return svg && value == "http://www.w3.org/1999/xlink"
	}
	if key == "href" || key == "xlink:href" || key == "src" || key == "action" || key == "formaction" || key == "poster" || key == "cite" {
		if svg {
			return value == "" || validFragment(value)
		}
		// templ applies its own narrower URL heuristic to a.href/form.action.
		// Refuse even safe relative URLs that it would rewrite (e.g. #id:x),
		// rather than silently change the source or bypass its sanitizer.
		if (tag == "a" && key == "href" || tag == "form" && key == "action") && string(templ.URL(value)) != value {
			return false
		}
		return safeURL(value, (key == "href" && tag == "a"))
	}
	// Space-separated ping URLs, srcset and CSS-bearing attrs need their own
	// grammar. srcset/style are not allowlisted; ping is refused when nonempty.
	if key == "ping" {
		return value == ""
	}
	if svg {
		lower := strings.ToLower(value)
		if strings.ContainsAny(value, "\\<>;") || strings.Contains(lower, "expression") || strings.Contains(lower, "@import") {
			return false
		}
		if strings.Contains(lower, "url") {
			return strings.HasPrefix(value, "url(") && strings.HasSuffix(value, ")") && validFragment(value[4:len(value)-1])
		}
	}
	return true
}

func validFragment(s string) bool {
	if len(s) < 2 || s[0] != '#' {
		return false
	}
	for _, c := range s[1:] {
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || strings.ContainsRune("_-.:", c)) {
			return false
		}
	}
	return true
}

func safeURL(s string, contact bool) bool {
	if s != strings.TrimSpace(s) || strings.ContainsRune(s, '\\') || strings.HasPrefix(s, "//") {
		return false
	}
	for _, c := range s {
		if c < 32 || c == 127 {
			return false
		}
	}
	u, err := url.Parse(s)
	if err != nil || u.User != nil {
		return false
	}
	switch strings.ToLower(u.Scheme) {
	case "":
		return true
	case "http", "https":
		return u.Host != ""
	case "mailto", "tel":
		return contact && u.Opaque != ""
	default:
		return false
	}
}

func invalidParent(stack []htmlFrame, name string) bool {
	parent := ""
	if len(stack) > 0 {
		parent = stack[len(stack)-1].name
	}
	// Require explicit table containers; browser foster-parenting and implicit
	// wrappers are not a source-to-source transformation in this first grammar.
	switch name {
	case "caption", "colgroup", "thead", "tbody", "tfoot":
		if parent != "table" {
			return true
		}
	case "tr":
		if parent != "thead" && parent != "tbody" && parent != "tfoot" {
			return true
		}
	case "td", "th":
		if parent != "tr" {
			return true
		}
	case "col":
		if parent != "colgroup" {
			return true
		}
	}
	for _, f := range stack {
		if f.name == "p" && wordsBlock[name] || f.name == "a" && name == "a" || f.name == "button" && name == "button" || f.name == "form" && name == "form" {
			return true
		}
	}
	if parent == "table" {
		return !wordsTable[name]
	}
	if parent == "thead" || parent == "tbody" || parent == "tfoot" {
		return name != "tr"
	}
	if parent == "tr" {
		return name != "td" && name != "th"
	}
	if parent == "select" {
		return name != "option" && name != "optgroup"
	}
	if parent == "optgroup" {
		return name != "option"
	}
	if parent == "option" {
		return true
	}
	return false
}

var wordsBlock = words(`address article aside blockquote details div dl fieldset figcaption figure footer form h1 h2 h3 h4 h5 h6 header hgroup hr main menu nav ol p pre search section table ul`)
var wordsTable = words(`caption colgroup thead tbody tfoot`)

// Validate the generated templ AST before returning it. All executable-looking
// source stays a quoted Go string; future emitter changes cannot quietly expand
// the grammar to imports, Go code, calls, dynamic attributes or raw HTML.
func validateTempl(source string) error {
	tf, err := templparser.ParseString(source)
	if err != nil {
		return fmt.Errorf("designconvert: generated templ failed parsing")
	}
	if strings.TrimSpace(tf.Package.Expression.Value) != "package converted" || len(tf.Header) != 0 || len(tf.Nodes) != 1 {
		return fmt.Errorf("designconvert: generated templ has unexpected top-level nodes")
	}
	t, ok := tf.Nodes[0].(*templparser.HTMLTemplate)
	if !ok || t.Expression.Value != "Specimen()" {
		return fmt.Errorf("designconvert: generated templ has an unexpected declaration")
	}
	return validateTemplNodes(t.Children)
}

func validateTemplNodes(nodes []templparser.Node) error {
	for _, node := range nodes {
		switch n := node.(type) {
		case *templparser.Element:
			if !htmlTags[n.Name] && !svgTags[n.Name] {
				return fmt.Errorf("designconvert: generated templ has an unexpected element")
			}
			for _, attr := range n.Attributes {
				a, ok := attr.(*templparser.ExpressionAttribute)
				if !ok {
					return fmt.Errorf("designconvert: generated templ has a nonliteral attribute")
				}
				if _, ok := a.Key.(templparser.ConstantAttributeKey); !ok || !literalString(a.Expression.Value) {
					return fmt.Errorf("designconvert: generated templ has a nonliteral attribute")
				}
			}
			if err := validateTemplNodes(n.Children); err != nil {
				return err
			}
		case *templparser.StringExpression:
			if !literalString(n.Expression.Value) {
				return fmt.Errorf("designconvert: generated templ has a nonliteral expression")
			}
		case *templparser.GoComment:
			var start, end int
			if n.Multiline {
				return fmt.Errorf("designconvert: generated templ has an unexpected comment")
			}
			if _, err := fmt.Sscanf(strings.TrimSpace(n.Contents), "source bytes %d..%d", &start, &end); err != nil || start < 0 || end < start || strings.TrimSpace(n.Contents) != fmt.Sprintf("source bytes %d..%d", start, end) {
				return fmt.Errorf("designconvert: generated templ has an unexpected comment")
			}
		case *templparser.HTMLComment, *templparser.Whitespace:
		default:
			return fmt.Errorf("designconvert: generated templ has an unexpected executable node")
		}
	}
	return nil
}

func literalString(s string) bool {
	e, err := goparser.ParseExpr(s)
	if err != nil {
		return false
	}
	lit, ok := e.(*ast.BasicLit)
	if !ok || lit.Kind != token.STRING {
		return false
	}
	_, err = strconv.Unquote(lit.Value)
	return err == nil
}
